import stdin, stdout from "@std/io/io.ms"
import lines from "@std/io/streams.ms"

fn run() Result[Unit, Error]:
    var input = lines(stdin())

    while true:
        line := try input.next()

        if text := line:
            try stdout().write("{text}\n")
        else:
            break

    return stdout().flush()

export fn main() Int:
    if run().is_error(): return 1

    return 0
